import React, { useState } from 'react';
import { Layout, Menu, Button, theme } from 'antd';
import { Routes, Route, useLocation, useNavigate } from 'react-router-dom';
import {
  MenuFoldOutlined,
  MenuUnfoldOutlined,
  ShoppingOutlined,
  TagsOutlined,
  GiftOutlined,
  TeamOutlined,
  CustomerServiceOutlined,
  ShoppingCartOutlined,
  BarChartOutlined,
  LogoutOutlined,
} from '@ant-design/icons';
import SanPhamPage from './SanPhamPage';
import DetailSanPhamPage from './DetailSanPhamPage';
import NhanVienPage from './NhanVienPage';
import VoucherPage from './VoucherPage';
import KhachHangPage from './KhachHangPage';
import ThuocTinhPage from './ThuocTinhPage';
import DonHangPage from './DonHangPage';
import OrderDetailPage from './OrderDetailPage';
import StatisticsPage from './StatisticsPage';
import BanHangTaiQuayPage from './BanHangTaiQuayPage';
import KhuyenMaiPage from './KhuyenMaiPage';
import ApDungKhuyenMaiPage from './ApDungKhuyenMaiPage';
import OrderDetailPOSPage from './OrderDetailPOSPage';
import UserDropdown from './components/UserDropdown';
import '../styles/AdminPanel.css';
import Swal from 'sweetalert2';

const { Header, Sider, Content } = Layout;

function AdminPanel() {
  const [collapsed, setCollapsed] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  const handleLogout = async () => {
    const result = await Swal.fire({
      title: 'Bạn có chắc chắn muốn đăng xuất?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Đăng xuất',
      cancelButtonText: 'Hủy',
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
    });
    if (result.isConfirmed) {
      localStorage.removeItem('adminToken');
      localStorage.removeItem('adminUser');
      Swal.fire({
        icon: 'success',
        title: 'Đã đăng xuất thành công',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1500,
        width: 250
      });
      navigate('/admin-login');
    }
  };

  const menuItems = [
    {
      key: 'statistics',
      icon: <BarChartOutlined />,
      label: 'Thống Kê',
      onClick: () => navigate('/admin-panel/statistics'),
    },
    {
      key: 'banhang',
      icon: <ShoppingCartOutlined />,
      label: 'Bán hàng tại quầy',
      onClick: () => navigate('/admin-panel/banhang'),
    },
    {
      key: 'orders',
      icon: <ShoppingCartOutlined />,
      label: 'Đơn Hàng',
      onClick: () => navigate('/admin-panel/orders'),
    },
    {
      key: 'products',
      icon: <ShoppingOutlined />,
      label: 'Sản Phẩm',
      onClick: () => navigate('/admin-panel/products'),
    },
    {
      key: 'attributes',
      icon: <TagsOutlined />,
      label: 'Thuộc Tính',
      onClick: () => navigate('/admin-panel/attributes'),
    },
    {
      key: 'vouchers',
      icon: <GiftOutlined />,
      label: 'Voucher',
      onClick: () => navigate('/admin-panel/vouchers'),
    },
    {
      key: 'promotions',
      icon: <TagsOutlined />,
      label: 'Khuyến Mãi',
      onClick: () => navigate('/admin-panel/promotions'),
    },
    {
      key: 'customers',
      icon: <CustomerServiceOutlined />,
      label: 'Khách Hàng',
      onClick: () => navigate('/admin-panel/customers'),
    },
    {
      key: 'staff',
      icon: <TeamOutlined />,
      label: 'Nhân Viên',
      onClick: () => navigate('/admin-panel/staff'),
    },
  ];

  const getSelectedKey = () => {
    const pathParts = location.pathname.split('/');
    const lastPart = pathParts[pathParts.length - 1];
    // Nếu đường dẫn là /admin-panel, đặt mặc định là products
    if (lastPart === 'admin-panel') {
      return 'products';
    }
    return lastPart;
  };

  const { token: { colorBgContainer } } = theme.useToken();

  return (
    <Layout>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        theme="dark"
        style={{
          position: 'fixed',
          left: 0,
          top: 0,
          height: '100vh',
          zIndex: 100,
          overflow: 'auto',
        }}
        width={200}
      >
        <div className="sidebar-logo">
          <img src="/logo.png" alt="Logo" />
        </div>
        <div className="sidebar-title">ADMIN</div>
        <Menu
          theme="dark"
          mode="inline"
          selectedKeys={[getSelectedKey()]}
          items={menuItems}
        />

        {/* Nút đăng xuất ở cuối sidebar */}
        <div style={{
          position: 'absolute',
          bottom: 20,
          left: 0,
          right: 0,
          padding: '0 16px'
        }}>
          <Button
            type="text"
            icon={<LogoutOutlined />}
            onClick={handleLogout}
            style={{
              width: '100%',
              height: 40,
              color: '#fff',
              border: '1px solid rgba(255, 255, 255, 0.2)',
              borderRadius: 6,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 8
            }}
            className="logout-button"
          >
            Đăng xuất
          </Button>
        </div>
      </Sider>
      <Layout className="site-layout" style={{ marginLeft: collapsed ? 80 : 200, transition: 'margin-left 0.2s' }}>
        <Header style={{ padding: 0, background: colorBgContainer, display: 'flex', alignItems: 'center', justifyContent: 'space-between', position: 'sticky', top: 0, zIndex: 10 }}>
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <Button
              type="text"
              icon={collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />}
              onClick={() => setCollapsed(!collapsed)}
              style={{
                fontSize: '16px',
                width: 64,
                height: 64,
              }}
            />
            <h2 style={{ margin: 0, marginLeft: 16 }}></h2>
          </div>

          <div style={{ marginRight: 24 }}>
            <UserDropdown />
          </div>
        </Header>
        <Content style={{ margin: '24px 16px', padding: 24, background: '#fff', borderRadius: '8px', boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)', minHeight: '100vh', overflow: 'auto' }}>
          <Routes>
            <Route index element={<SanPhamPage />} />
            <Route path="products" element={<SanPhamPage />} />
            <Route path="products/:id" element={<DetailSanPhamPage />} />
            <Route path="staff" element={<NhanVienPage />} />
            <Route path="vouchers" element={<VoucherPage />} />
            <Route path="promotions" element={<KhuyenMaiPage />} />
            <Route path="ap-dung-khuyen-mai/:khuyenMaiId" element={<ApDungKhuyenMaiPage />} />
            <Route path="customers" element={<KhachHangPage />} />
            <Route path="attributes/*" element={<ThuocTinhPage />} />
            <Route path="orders" element={<DonHangPage />} />
            <Route path="orders/:orderId" element={<OrderDetailPage />} />
            <Route path="pos-orders/:id" element={<OrderDetailPOSPage />} />
            <Route path="statistics" element={<StatisticsPage />} />
            <Route path="banhang" element={<BanHangTaiQuayPage />} />
          </Routes>
        </Content>
      </Layout>
    </Layout>
  );
}

export default AdminPanel;

import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Card, Checkbox, Button, Space, Typography, Tag, Row, Col, Tooltip, message } from 'antd';
import { ArrowLeftOutlined, SaveOutlined } from '@ant-design/icons';
import axios from 'axios';
import Swal from 'sweetalert2';
import moment from 'moment';
import '../styles/AdminPanel.css';

const { Title, Text } = Typography;

const ApDungKhuyenMaiPage = () => {
  const { khuyenMaiId } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [listSPCT, setListSPCT] = useState([]);
  const [promotion, setPromotion] = useState(null);
  const [selectedSPCTIds, setSelectedSPCTIds] = useState([]);

  // State cho bộ log
  const [filterTenSanPham, setFilterTenSanPham] = useState('');
  const [filterMauSac, setFilterMauSac] = useState('');
  const [filterKichThuoc, setFilterKichThuoc] = useState('');
  const [errorState, setErrorState] = useState(null);

  const fetchPromotionDetails = useCallback(async () => {
    try {
      const response = await axios.get(`http://localhost:8080/api/khuyenmai/${khuyenMaiId}`);
      setPromotion(response.data);
    } catch (error) {
      console.error('Lỗi khi lấy thông tin khuyến mãi:', error);
      Swal.fire({
        icon: 'error',
        title: 'Không thể tải thông tin khuyến mãi',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1500,
        width: 250
      });
    }
  }, [khuyenMaiId]);

  const fetchSPCTList = useCallback(async () => {
    setLoading(true);
    try {
      // Sử dụng API mới để lấy sản phẩm có thể áp dụng khuyến mãi
      const response = await axios.get(`http://localhost:8080/api/san-pham-chi-tiet/available-for-promotion/${khuyenMaiId}`);

      // Debug log để xem cấu trúc dữ liệu
      if (response.data && response.data.length > 0) {

      }

      setListSPCT(response.data);
      console.log("📥 Danh sách SPCT từ Backend:");
      response.data.forEach(item => {
        if (item.idKhuyenMai) {
          console.log(`- SP ID ${item.id}: ${item.tenSanPham} | KM ID: ${item.idKhuyenMai} | Tên KM: ${item.tenKhuyenMai}`);
        }
      });

      // Tự động tích các sản phẩm đã áp dụng khuyến mãi này
      if (Array.isArray(response.data)) {
        const selectedIds = response.data
          .filter(spct => {
            const promoId = spct.idKhuyenMai || spct.khuyenMai?.id;
            return promoId && promoId == khuyenMaiId;
          })
          .map(spct => spct.id);
        setSelectedSPCTIds(selectedIds);
      }
    } catch (error) {
      console.error('Lỗi khi lấy danh sách sản phẩm chi tiết:', error);
      Swal.fire({
        icon: 'error',
        title: 'Không thể tải danh sách sản phẩm',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1500,
        width: 250
      });
      setListSPCT([]);
      setSelectedSPCTIds([]);
      setErrorState(error.message || 'Lỗi không xác định');
    } finally {
      setLoading(false);
    }
  }, [khuyenMaiId]);

  useEffect(() => {
    fetchPromotionDetails();
    fetchSPCTList();
  }, [fetchPromotionDetails, fetchSPCTList]);

  const handleApplyKhuyenMai = async () => {
    if (!khuyenMaiId || selectedSPCTIds.length === 0) {
      Swal.fire({
        icon: 'warning',
        title: 'Vui lòng chọn sản phẩm chi tiết!',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1800,
        width: 250
      });
      return;
    }

    // ✅ KIỂM TRA: Sản phẩm đã có khuyến mãi khác đang hoạt động
    const conflictProducts = listSPCT.filter(spct => {
      // Sử dụng == để so sánh ID (tránh lỗi kiểu chuỗi vs số)
      const isSelected = selectedSPCTIds.some(id => id == spct.id);
      if (!isSelected) return false;

      const spPromoId = spct.idKhuyenMai || spct.khuyenMai?.id;
      // Khuyến mãi khác đang áp dụng (không phải khuyenMaiId hiện tại)
      if (spPromoId && spPromoId != khuyenMaiId) {
        return true; // Có xung đột
      }
      return false;
    });

    if (conflictProducts.length > 0) {
      const productListHtml = conflictProducts.map(p => {
        const tenKm = p.tenKhuyenMai || p.khuyenMai?.tenKhuyenMai || 'Khuyến mãi khác';
        return `<div style="text-align: left; margin-bottom: 5px; font-size: 13px;">• <b>${getProductName(p)}</b> (<span style="color: #f5222d;">${tenKm}</span>)</div>`;
      }).join('');

      const overrideConfirm = await Swal.fire({
        title: 'Xung đột khuyến mãi!',
        html: `
          <div style="margin-bottom: 15px; text-align: left;">Có <b>${conflictProducts.length}</b> sản phẩm đang áp dụng khuyến mãi khác vẫn còn hiệu lực:</div>
          <div style="max-height: 200px; overflow-y: auto; background: #fff2f0; padding: 12px; border-radius: 8px; border: 1px solid #ffccc7;">
            ${productListHtml}
          </div>
          <div style="margin-top: 15px; font-weight: 500; color: #333;">Bạn có chắc chắn muốn thay thế bằng khuyến mãi mới này không?</div>
        `,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ff4d4f',
        cancelButtonColor: '#6c757d',
        confirmButtonText: 'Xác nhận thay thế',
        cancelButtonText: 'Hủy',
        width: 500
      });

      if (!overrideConfirm.isConfirmed) return;
    } else {
      // Xác nhận áp dụng bình thường nếu không có xung đột
      const confirmResult = await Swal.fire({
        title: 'Xác nhận áp dụng khuyến mãi?',
        text: `Bạn có chắc chắn muốn áp dụng khuyến mãi này cho ${selectedSPCTIds.length} sản phẩm đã chọn?`,
        icon: 'question',
        showCancelButton: true,
        confirmButtonColor: '#1677ff',
        cancelButtonColor: '#6c757d',
        confirmButtonText: 'Xác nhận áp dụng',
        cancelButtonText: 'Hủy'
      });

      if (!confirmResult.isConfirmed) return;
    }

    try {
      setLoading(true);
      await axios.post(`http://localhost:8080/api/khuyen-mai/ap-dung/${khuyenMaiId}`, selectedSPCTIds);

      Swal.fire({
        icon: 'success',
        title: 'Áp dụng khuyến mãi thành công!',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1500,
        width: 250
      });

      // Refresh lại danh sách sản phẩm để cập nhật giá
      await fetchSPCTList();

      // Chờ 1 giây rồi mới chuyển trang
      setTimeout(() => {
        navigate('/admin-panel/promotions');
      }, 1000);
    } catch (error) {
      console.error('Lỗi khi áp dụng khuyến mãi:', error);
      let errorMessage = 'Áp dụng thất bại!';
      if (error.response && error.response.data) {
        errorMessage = error.response.data;
      }
      Swal.fire({
        icon: 'error',
        title: errorMessage,
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 3000,
        width: 350
      });
    } finally {
      setLoading(false);
    }
  };

  const handleRemovePromotion = async () => {
    // Lấy danh sách sản phẩm đã được áp dụng khuyến mãi này
    const appliedProducts = listSPCT.filter(spct => {
      const spPromoId = spct.idKhuyenMai || spct.khuyenMai?.id;
      return spPromoId == khuyenMaiId;
    });

    if (appliedProducts.length === 0) {
      Swal.fire({
        icon: 'info',
        title: 'Không có sản phẩm nào đang áp dụng khuyến mãi này',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 2000,
        width: 300
      });
      return;
    }

    // Bổ sung xác nhận bỏ áp dụng
    const confirmResult = await Swal.fire({
      title: 'Xác nhận gỡ khuyến mãi?',
      text: `Bạn có chắc chắn muốn gỡ khuyến mãi này khỏi ${appliedProducts.length} sản phẩm đang áp dụng?`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#ff4d4f',
      cancelButtonColor: '#6c757d',
      confirmButtonText: 'Xác nhận gỡ',
      cancelButtonText: 'Hủy'
    });

    if (!confirmResult.isConfirmed) return;

    try {
      setLoading(true);
      const productIds = appliedProducts.map(spct => spct.id);
      await axios.post(`http://localhost:8080/api/khuyen-mai/${khuyenMaiId}/bo-ap-dung`, productIds);

      Swal.fire({
        icon: 'success',
        title: 'Bỏ áp dụng khuyến mãi thành công!',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1500,
        width: 250
      });

      // Refresh danh sách sản phẩm
      fetchSPCTList();
    } catch (error) {
      console.error('Lỗi khi bỏ áp dụng khuyến mãi:', error);
      Swal.fire({
        icon: 'error',
        title: 'Bỏ áp dụng thất bại!',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1800,
        width: 250
      });
    } finally {
      setLoading(false);
    }
  };

  // Tính giá sau khuyến mãi
  const calculateDiscountedPrice = (originalPrice, discountPercent) => {
    if (!originalPrice || !discountPercent) return originalPrice;
    return Math.round(originalPrice * (1 - discountPercent / 100));
  };

  // Format giá tiền
  const formatPrice = (price) => {
    return price ? price.toLocaleString('vi-VN') + '₫' : '...';
  };

  // Hàm helper để lấy tên sản phẩm an toàn
  const getProductName = (spct) => {
    if (typeof spct.tenSanPham === 'string') return spct.tenSanPham;
    if (spct.sanPham?.tenSanPham) return spct.sanPham.tenSanPham;
    return 'SP';
  };

  // Hàm helper để lấy tên màu sắc an toàn
  const getColorName = (spct) => {
    if (typeof spct.mauSac === 'string') return spct.mauSac;
    if (spct.mauSac?.tenMauSac) return spct.mauSac.tenMauSac;
    return '...';
  };

  // Hàm helper để lấy tên kích thước an toàn
  const getSizeName = (spct) => {
    if (typeof spct.kichThuoc === 'string') return spct.kichThuoc;
    if (spct.kichThuoc?.tenKichThuoc) return spct.kichThuoc.tenKichThuoc;
    return '...';
  };

  // Hàm helper để lấy hình ảnh an toàn
  const getProductImage = (spct) => {
    // Thử nhiều cách để lấy ảnh từ sản phẩm chi tiết
    let images = spct.images || spct.sanPham?.images || spct.sanPham?.images;



    if (!images) return '/logo192.png';

    // Nếu là mảng, lấy phần tử đầu
    if (Array.isArray(images)) {
      const img = images[0];
      if (!img) return '/logo192.png';
      if (img.startsWith('http')) return img;
      if (img.startsWith('/')) return 'http://localhost:8080' + img;
      return `http://localhost:8080/images/${encodeURIComponent(img)}`;
    }

    // Nếu là chuỗi nhiều ảnh, lấy ảnh đầu
    if (typeof images === 'string' && images.includes(',')) {
      const img = images.split(',')[0].trim();
      if (!img) return '/logo192.png';
      if (img.startsWith('http')) return img;
      if (img.startsWith('/')) return 'http://localhost:8080' + img;
      return `http://localhost:8080/images/${encodeURIComponent(img)}`;
    }

    // Nếu là chuỗi đơn
    if (typeof images === 'string') {
      const img = images.trim();
      if (!img) return '/logo192.png';
      if (img.startsWith('http')) return img;
      if (img.startsWith('/')) return 'http://localhost:8080' + img;
      return `http://localhost:8080/images/${encodeURIComponent(img)}`;
    }

    return '/logo192.png';
  };

  // Log sản phẩm theo filter
  const filteredListSPCT = listSPCT.filter(spct => {
    const tenSanPham = getProductName(spct).toLowerCase();
    const mauSac = getColorName(spct).toLowerCase();
    const kichThuoc = getSizeName(spct).toLowerCase();

    const matchTenSanPham = !filterTenSanPham || tenSanPham.includes(filterTenSanPham.toLowerCase());
    const matchMauSac = !filterMauSac || mauSac.includes(filterMauSac.toLowerCase());
    const matchKichThuoc = !filterKichThuoc || kichThuoc.includes(filterKichThuoc.toLowerCase());

    return matchTenSanPham && matchMauSac && matchKichThuoc;
  });

  // Lấy danh sách màu sắc và kích thước duy nhất cho filter
  const uniqueMauSac = [...new Set(listSPCT.map(spct => getColorName(spct)).filter(Boolean))];
  const uniqueKichThuoc = [...new Set(listSPCT.map(spct => getSizeName(spct)).filter(Boolean))];

  // Kiểm tra khuyến mãi có đang hoạt động không
  const isPromotionActive = (promotion) => {
    if (!promotion) return false;

    const now = moment();
    const startDate = moment(promotion.ngayBatDau);
    const endDate = moment(promotion.ngayKetThuc);

    return now.isSameOrAfter(startDate) && now.isSameOrBefore(endDate);
  };

  // Lấy trạng thái khuyến mãi
  const getPromotionStatus = (promotion) => {
    if (!promotion) return { text: 'Không xác định', color: 'default' };

    const now = moment();
    const startDate = moment(promotion.ngayBatDau);
    const endDate = moment(promotion.ngayKetThuc);

    if (now.isBefore(startDate)) {
      return { text: 'Chưa bắt đầu', color: 'orange' };
    } else if (now.isAfter(endDate)) {
      return { text: 'Đã hết hạn', color: 'red' };
    } else {
      return { text: 'Đang hoạt động', color: 'green' };
    }
  };

  return (
    <div className="admin-content-page">
      <div className="page-header">
        <Space>
          <Button
            icon={<ArrowLeftOutlined />}
            onClick={() => navigate('/admin-panel/promotions')}
          >
            Quay lại
          </Button>
          <Title level={2} style={{ margin: 0 }}>
            Áp Dụng Khuyến Mãi
          </Title>
        </Space>
      </div>

      {promotion && (
        <Card style={{ marginBottom: 16 }}>
          <Title level={4}>Thông Tin Khuyến Mãi</Title>
          <Space direction="vertical" size="small">
            <Text><strong>Tên khuyến mãi:</strong> {promotion.tenKhuyenMai}</Text>
            <Text><strong>Giá trị:</strong> {promotion.giaTri}%</Text>
            <Text><strong>Trạng thái:</strong>
              <Tag color={getPromotionStatus(promotion).color}>
                {getPromotionStatus(promotion).text}
              </Tag>
            </Text>
            <Text><strong>Thời gian:</strong> {moment(promotion.ngayBatDau).format('DD/MM/YYYY HH:mm')} - {moment(promotion.ngayKetThuc).format('DD/MM/YYYY HH:mm')}</Text>
          </Space>

