            );

            const variants = variantRes.data || [];

            const tongSoLuong = variants.reduce(
              (sum, v) => sum + (v.soLuong || 0),
              0
            );

            return {
              ...product,
              tongSoLuong
            };

          } catch (error) {
            return {
              ...product,
              tongSoLuong: 0
            };
          }
        })
      );

