      <Row gutter={[16, 16]}>
        <Col xs={24}>
          <Card size="small"
            title={
              <Space>
                <RiseOutlined />
                <span>Số Đơn Hàng Theo Ngày {dateRange[0] ? `(${dateRange[0].format('DD/MM/YYYY')} - ${dateRange[1].format('DD/MM/YYYY')})` : `(Tháng này)`}</span>
              </Space>
