              <Space>
                <ShoppingCartOutlined />
                <span>Top Sản Phẩm Bán Chạy {dateRange[0] ? `(${dateRange[0].format('DD/MM/YYYY')} - ${dateRange[1].format('DD/MM/YYYY')})` : `(Tháng này)`}</span>
