import React, { useState, useEffect } from 'react';
import Swal from 'sweetalert2';
import { Table, Button, Modal, Form, Input, Select, Space, message, Switch } from 'antd';
import {TagOutlined, SearchOutlined } from '@ant-design/icons';
import '../styles/AdminPanel.css';

const { Option } = Select;
const { Search } = Input;

export default function XuatXuPage() {
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [form] = Form.useForm();
  const [xuatXus, setXuatXus] = useState([]);
  const [showTrashModal, setShowTrashModal] = useState(false);
  const [trashList, setTrashList] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearching, setIsSearchọng] = useState(false);

  const fetchAll = () => {
    fetch('http://localhost:8080/api/xuat-xu/getAllFull')
      .then(response => response.json())
      .then(data => setXuatXus(data));
  };
  const fetchTrash = () => {
    fetch('http://localhost:8080/api/xuat-xu/getThungRac')
      .then(res => res.json())
      .then(data => setTrashList(data));
  };

  const handleSearch = (value) => {
    if (!value.trim()) {
      fetchAll();
      setSearchTerm('');
      return;
    }

    setIsSearchọng(true);
    setSearchTerm(value);

    fetch(`http://localhost:8080/api/xuat-xu/search?name=${encodeURIComponent(value)}`)
      .then(response => {
        if (!response.ok) {
          throw new Error('Lỗi tìm kiếm');
        }
        return response.json();
      })
      .then(data => {
        setXuatXus(data);
        setIsSearchọng(false);
      })
      .catch(error => {
        console.error('Lỗi khi tìm kiếm:', error);
        message.error('Có lỗi xảy ra khi tìm kiếm');
        setIsSearchọng(false);
      });
  };

  const handleClearSearch = () => {
    setSearchTerm('');
    fetchAll();
  };
  const handleRestore = async (id) => {
    const result = await Swal.fire({
      title: 'Xác nhận khôi phục xuất xứ này?',
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#3085d6',
      cancelButtonColor: '#6c757d',
      confirmButtonText: 'Khôi phục',
      cancelButtonText: 'Hủy'
    });

    if (!result.isConfirmed) return;

    fetch(`http://localhost:8080/api/xuat-xu/khoi-phuc/${id}`, { method: 'PUT' })
      .then(res => { if (!res.ok) throw new Error(); })
      .then(() => {
        Swal.fire({ icon: 'success', title: 'Khôi phục thành công', toast: true, position: 'top-end', showConfirmButton: false, timer: 1500, width: 250 });
        fetchTrash();
        fetchAll();
      })
      .catch(() => {
        Swal.fire({ icon: 'error', title: 'Khôi phục thất bại', toast: true, position: 'top-end', showConfirmButton: false, timer: 1500, width: 250 });
      });
  };

  useEffect(() => {
    fetch('http://localhost:8080/api/kich-thuoc/getAllFull')
      .then(response => response.json())
      .then(data => {
        console.log('DATA KICH THUOC:', data);
        setKichThuocs(data);
      })
      .catch(error => console.error('Lỗi khi gọi API kích thước:', error));
  }, []);

  useEffect(() => {
    fetch('http://localhost:8080/api/xuat-xu/getAllFull')
      .then(response => response.json())
      .then(data => setXuatXus(data))
      .catch(error => console.error('Lỗi khi gọi API kích thước:', error));
  }, []);

  const columns = [
    { 
      title: 'STT', 
      key: 'stt',
      render: (text, record, index) => index + 1 
    },
    { title: 'Tên Xuất Xứ', dataIndex: 'tenXuatXu', key: 'tenXuatXu' },
    {
      title: 'Trạng Thái',
      dataIndex: 'trangThai',
      key: 'trangThai',
      render: (value, record) => (
        <Switch
          checked={value === 1}
          checkedChildren=""
          unCheckedChildren=""
          style={{ backgroundColor: value === 1 ? '#43a047' : '#e53935' }}
          onChange={() => handleChangeTrangThai(record)}
        />
      ),
    },
    {
      title: 'Hành Động',
      key: 'actions',
      render: (_, record) => (
        <Space size="middle">
          <Button type="primary" onClick={() => handleEdit(record)}>Sửa</Button>
          {/* <Button type="danger" onClick={() => handleDelete(record.id)}>Xóa</Button> */}
        </Space>
      ),
    },
  ];

  // Thêm hàm chuyển trạng thái
  const handleChangeTrangThai = async (item) => {
    const isActive = item.trangThai === 1;
    const result = await Swal.fire({
      title: isActive ? 'Bạn có chắc chắn muốn ngừng hoạt động xuất xứ này?' : 'Bạn có chắc chắn muốn chuyển sang hoạt động?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonText: 'Có',
      cancelButtonText: 'Không',
    });
    if (!result.isConfirmed) return;
    try {
      if (isActive) {
        await fetch(`http://localhost:8080/api/xuat-xu/del/${item.id}`, { method: 'DELETE' });
      } else {
        await fetch(`http://localhost:8080/api/xuat-xu/khoi-phuc/${item.id}`, { method: 'PUT' });
      }
      fetchAll();
      Swal.fire({
        icon: 'success',
        title: 'Cập nhật trạng thái thành công!',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 1500,
        width: 250
      });
    } catch (error) {
      Swal.fire('Lỗi', 'Không thể cập nhật trạng thái', 'error');
    }
  };

  const showModal = () => {
    setIsModalVisible(true);
  };

  const handleCancel = () => {
    setIsModalVisible(false);
    setEditingItem(null);
    form.resetFields();
  };

  const handleAdd = () => {
    setEditingItem(null);
    form.resetFields();
    showModal();
  };

  const handleEdit = (item) => {
    setEditingItem(item);
    form.setFieldsValue({
      ...item,
      tenXuatXu: item.tenXuatXu
    });
    showModal();
  };

  const onFinish = async (values) => {
    const actionText = editingItem ? "Cập nhật" : "Thêm mới";
    const result = await Swal.fire({
      title: `Xác nhận ${actionText.toLowerCase()} xuất xứ?`,
      text: "Vui lòng kiểm tra kỹ thông tin trước khi xác nhận.",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#3085d6',
      cancelButtonColor: '#6c757d',
      confirmButtonText: 'Xác nhận',
      cancelButtonText: 'Hủy'
    });

    if (!result.isConfirmed) return;

    if (editingItem) {
      // Cập nhật
      fetch(`http://localhost:8080/api/xuat-xu/update/${editingItem.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: editingItem.id,
          tenXuatXu: values.tenXuatXu,
          trangThai: Number(values.trangThai)
        }),
      })
        .then(response => {
          if (!response.ok) {
            return response.text().then(errorMessage => {
              throw new Error(errorMessage);
            });
          }
          return response.json();
        })
        .then(data => {
          Swal.fire({
            icon: 'success',
            title: 'Sửa thành công',
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 1500,
            width: 250
          });
          fetchAll();
        })
        .catch(error => {
          Swal.fire({
            icon: 'error',
            title: 'Sửa thất bại',
            text: error.message || 'Có lỗi xảy ra khi sửa xuất xứ',
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 3000,
            width: 350
          });
          console.error(error);
        });
    } else {
      // Thêm mới
      fetch('http://localhost:8080/api/xuat-xu/add', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tenXuatXu: values.tenXuatXu,
          trangThai: Number(values.trangThai)
        }),
      })
        .then(response => {
          if (!response.ok) {
            return response.text().then(errorMessage => {
              throw new Error(errorMessage);
            });
          }
          return response.json();
        })
        .then(data => {
          Swal.fire({
            icon: 'success',
            title: 'Thêm thành công',
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 1500,
            width: 250
          });
          fetchAll();
        })
        .catch(error => {
          Swal.fire({
            icon: 'error',
            title: 'Thêm thất bại',
            text: error.message || 'Có lỗi xảy ra khi thêm xuất xứ',
            toast: true,
            position: 'top-end',
            showConfirmButton: false,
            timer: 3000,
            width: 350
          });
          console.error(error);
        });
    }
    handleCancel();
  };

  return (
    <div className="admin-content-page">
      <div className="page-header">
        <h2 className="page-title">Quản lý Xuất Xứ</h2>
        <div style={{ display: 'flex', gap: 10 }}>
          <Button type="primary" onClick={handleAdd}>Thêm Xuất Xứ Mới</Button>
        </div>
      </div>

      <div style={{ marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
        <Search
          placeholder="Tìm kiếm xuất xứ theo tên..."
          prefix={<SearchOutlined />}
          style={{ width: 400 }}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          onPressEnter={() => handleSearch(searchTerm)}
          onSearch={() => handleSearch(searchTerm)}
          enterButton
          loading={isSearching}
        />
        {searchTerm && (
          <Button type="link" onClick={handleClearSearch}>
            Xóa tìm kiếm
          </Button>
        )}
      </div>

      <Table 
        dataSource={xuatXus} 
        columns={columns} 
        rowKey="id" 
        pagination={false}
        loading={isSearching}
      />

      <Modal
        title={editingItem ? "Sửa Xuất Xứ" : "Thêm Xuất Xứ"}
        visible={isModalVisible}
        onCancel={handleCancel}
        footer={null}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          initialValues={{ trangThai: 1 }}
        >
          {editingItem && (
            <Form.Item name="id" label="ID">
              <Input disabled />
            </Form.Item>
          )}
          <Form.Item
            name="tenXuatXu"
            label="Tên Xuất Xứ"
            rules={[{ required: true, message: 'Vui lòng nhập Tên Xuất Xứ!' }]}
          >
            <Input prefix={<TagOutlined />} placeholder="Tên Xuất Xứ" />
          </Form.Item>
          <Form.Item
            name="trangThai"
            label="Trạng Thái"
            rules={[{ required: true, message: 'Vui lòng chọn Trạng Thái!' }]}
          >
            <Select placeholder="Chọn Trạng Thái">
              <Option value={1}>Đang hoạt động</Option>
              <Option value={0}>Không hoạt động</Option>
            </Select>
          </Form.Item>
          <Form.Item>
            <Button type="primary" htmlType="submit">
              {editingItem ? "Cập Nhật" : "Thêm Mới"}
            </Button>
            <Button onClick={handleCancel} style={{ marginLeft: 8 }}>
              Hủy
            </Button>
          </Form.Item>
        </Form>
      </Modal>

      <Modal
        title="Danh sách xuất xứ ngừng hoạt động"
        visible={showTrashModal}
        onCancel={() => setShowTrashModal(false)}
        footer={null}
      >
        <Table
          dataSource={trashList}
          columns={[
            { title: 'ID', dataIndex: 'id', key: 'id' },
            { title: 'Tên Xuất Xứ', dataIndex: 'tenXuatXu', key: 'tenXuatXu' },
            { title: 'Trạng Thái', dataIndex: 'trangThai', key: 'trangThai', render: v => v === 1 ? 'Đang hoạt động' : 'Ngừng hoạt động' },
            {
              title: 'Hành động',
              key: 'actions',
              render: (_, record) => (
                <Button type="primary" onClick={() => handleRestore(record.id)}>Khôi phục</Button>
              ),
            },
          ]}
          rowKey="id"
          pagination={false}
        />
      </Modal>
    </div>
  );
}

