  if (!raw) return `${config.baseUrl}images/logo.png`;
  if (typeof raw === 'string' && (raw.startsWith('http://') || raw.startsWith('https://'))) return raw;
  let firstImg = typeof raw === 'string' ? raw.split(',')[0].trim() : String(raw).trim();
