    // Xử lý các trạng thái đặc biệt bên ngoài luồng chuẩn
    if (currentStatus === 8) {
      const stop = TRANG_THAI.find(t => t.value === 8) || { value: 8, label: 'Chờ thanh toán', color: '#d97706' };
